def mark_existing_applied(apps, schema_editor):
    # Subscriptions that exist before payment tracking already have their
    # modules applied — record that, so nobody loses access. Payment stays
    # 'pending' (never assumed paid), except website sign-ups, which are
    # approved only after the gateway verified the payment.
    CompanySubscription = apps.get_model('tenants', 'CompanySubscription')
    for sub in CompanySubscription.objects.all():
        sub.provisioning_status = 'success'
        sub.provisioned_at = sub.updated_at
        if sub.source == 'website':
            sub.payment_status = 'paid'
        sub.save(update_fields=['provisioning_status', 'provisioned_at', 'payment_status'])


